// English inside Hebrew text: isolate each Latin run so punctuation stays on its own side (⁦ … ⁩)
function iso(t) { return String(t == null ? '' : t).replace(/[A-Za-z](?:[A-Za-z0-9' ,.!?\-]*[A-Za-z0-9!?.])?/g, m => '\u2066' + m + '\u2069'); }
