// ---------- visual helpers (ten frame, rods, groups, array, number line) ----------
function visModel(v, scale) {
  const s = scale || 1;
  const out = { tenframe: [], rods: [], ones: [], groups: [], array: [], line: { w: 0, ticks: [], markStyle: 'display: none', arcStyle: 'display: none' }, isTen: false, isRods: false, isGroups: false, isArray: false, isLine: false };
  if (!v) return out;
  if (v.kind === 'tenframe') {
    out.isTen = true;
    const frames = Math.max(1, Math.ceil(v.n / 10));
    for (let f = 0; f < frames; f++) {
      const cells = [];
      for (let c = 0; c < 10; c++) { const idx = f * 10 + c; cells.push({ style: 'width: ' + Math.round(34 * s) + 'px; height: ' + Math.round(34 * s) + 'px; border-radius: 50%; background: ' + (idx < v.n ? '#FFC83D' : 'rgba(255,255,255,0.12)') + '; box-shadow: ' + (idx < v.n ? '0 0 10px rgba(255,200,61,0.6)' : 'none') }); }
      out.tenframe.push({ cells });
    }
  } else if (v.kind === 'rods') {
    out.isRods = true;
    for (let i = 0; i < v.tens; i++) out.rods.push({ k: i });
    for (let i = 0; i < v.ones; i++) out.ones.push({ k: i });
  } else if (v.kind === 'groups') {
    out.isGroups = true;
    for (let i = 0; i < v.g; i++) out.groups.push({ t: new Array(v.n + 1).join(v.e || '👽') });
  } else if (v.kind === 'array') {
    out.isArray = true;
    for (let r = 0; r < v.r; r++) out.array.push({ t: new Array(v.c + 1).join(v.e || '⭐') });
  } else if (v.kind === 'line') {
    out.isLine = true;
    const W = Math.round(720 * s), lo = v.lo, hi = v.hi, span = hi - lo;
    const step = span <= 20 ? 1 : 10;
    const ticks = [];
    for (let x = lo; x <= hi; x += step) {
      const big = span <= 20 ? true : true;
      const hl = (v.mark10 && x === 10) || (v.a === x) || (v.b === x && v.b != null);
      ticks.push({ label: String(x), style: 'position: absolute; left: ' + Math.round((x - lo) / span * W) + 'px; top: 0; width: 0; height: 100%', tick: 'position: absolute; left: -1px; top: 26px; width: 3px; height: ' + (big ? 22 : 12) + 'px; background: ' + (hl ? '#FFC83D' : '#C9C3F2'), lab: 'position: absolute; top: 54px; left: -20px; width: 40px; text-align: center; font-size: ' + (span <= 20 ? 16 : 18) + 'px; font-weight: ' + (hl ? 700 : 500) + '; color: ' + (hl ? '#FFC83D' : '#E6E1FF') });
    }
    const markX = v.mark != null ? Math.round((v.mark - lo) / span * W) : (v.a != null ? Math.round((v.a - lo) / span * W) : -999);
    out.line = { w: W, ticks, markStyle: 'position: absolute; top: -14px; left: ' + (markX - 20) + 'px; font-size: 34px; display: ' + (markX < -100 ? 'none' : 'block'),
                 arcStyle: 'display: ' + (v.b != null && v.a != null ? 'block' : 'none') + '; position: absolute; top: 4px; height: 30px; border: 3px solid #34D1BF; border-bottom: 0; border-radius: 30px 30px 0 0; left: ' + Math.round((Math.min(v.a || 0, v.b || 0) - lo) / span * W) + 'px; width: ' + Math.round(Math.abs((v.b || 0) - (v.a || 0)) / span * W) + 'px' };
  }
  return out;
}


